mapper.sql:
FROM t_content_unit cu JOIN t_document d ON d.id=cu.document_id
    JOIN t_source_version sv ON sv.id=d.source_version_id
    JOIN t_source s ON s.id=sv.source_id WHERE s.knowledge_base_id=#{kb}

mapper.select:
SELECT
  (SELECT COUNT(*) FROM t_claim WHERE knowledge_base_id=#{kb}
     AND status IN ('DRAFT','UNCERTAIN','CONFLICTED','PENDING_REVIEW')) pendingReviewClaim,
  (SELECT COUNT(*) FROM t_knowledge_card WHERE knowledge_base_id=#{kb}
     AND status IN ('DRAFT','UNCERTAIN','CONFLICTED','PENDING_REVIEW')) pendingReviewCard,
  (SELECT COUNT(*) FROM t_knowledge_conflict WHERE knowledge_base_id=#{kb} AND status='OPEN') conflict,
  (SELECT COUNT(*) FROM t_claim WHERE knowledge_base_id=#{kb} AND valid_to IS NOT NULL
     AND valid_to < NOW() AND (status IS NULL OR status NOT IN ('EXPIRED','SUPERSEDED','REJECTED'))) expired,
  (SELECT COUNT(*) FROM t_claim c WHERE c.knowledge_base_id=#{kb}
     AND NOT EXISTS(SELECT 1 FROM t_claim_evidence ce WHERE ce.claim_code=c.claim_code)) noEvidenceClaim,
  (SELECT COUNT(*) FROM t_knowledge_card k WHERE k.knowledge_base_id=#{kb}
     AND NOT EXISTS(SELECT 1 FROM t_knowledge_evidence ke WHERE ke.knowledge_code=k.knowledge_code)) noEvidenceCard,
  (SELECT COUNT(*) FROM t_claim WHERE knowledge_base_id=#{kb}
     AND confidence IS NOT NULL AND confidence < #{lowConfidence}) lowConfidenceClaim,
  (SELECT COUNT(*) FROM t_knowledge_card WHERE knowledge_base_id=#{kb}
     AND confidence IS NOT NULL AND confidence < #{lowConfidence}) lowConfidenceCard,
  (SELECT COUNT(*) FROM t_claim WHERE knowledge_base_id=#{kb} AND status='STALE') staleDerived

SELECT objectType,objectCode,displayTitle,status,confidence,updatedTime FROM (
  SELECT 'CARD' objectType,knowledge_code objectCode,title displayTitle,status,confidence,
         COALESCE(updated_time,created_time) updatedTime
    FROM t_knowledge_card WHERE knowledge_base_id=#{kb}
  UNION ALL
  SELECT 'CLAIM' objectType,claim_code objectCode,
         CONCAT(subject,' ',predicate,' ',LEFT(object_value,120)) displayTitle,status,confidence,
         COALESCE(updated_time,created_time) updatedTime
    FROM t_claim WHERE knowledge_base_id=#{kb}
) recent ORDER BY updatedTime DESC LIMIT #{limit}
